    import re
    from collections import Counter
    import sympy

    # ---------- Helper functions ----------
    def parse_num(s: str):
        """Extract the first numeric value from a string."""
        try:
            return float(s)
        except Exception:
            m = re.search(r"[-+]?\d*\.?\d+", s)
            return float(m.group(0)) if m else None

    def eval_expr(expr_str: str):
        """Safely evaluate a mathematical expression using SymPy.
        Returns a float or None if evaluation fails.
        """
        # Remove accidental labels and whitespace
        clean = re.sub(r"(?i)^.*?[=:]\s*", "", expr_str).replace(" ", "")
        if len(clean) > 200:
            return None
        try:
            expr = sympy.sympify(clean)
            return float(sympy.N(expr))
        except Exception:
            return None

    def extract(info_list, key):
        """Return the first Info with the given name, or None."""
        for info in info_list:
            if info.name == key:
                return info
        return None

    # ---------- Generate diverse CoT samples ----------
    N = 8  # number of CoT samples
    cot_instruction = (
        "Please think step by step and then solve the task. "
        "Provide two fields: 'solution' with the numeric answer (no extra text) and 'expression' with a single mathematical expression that evaluates to that answer. "
        "Use only digits, parentheses, and the operators +, -, *, /, **. DO NOT add explanatory text."
    )
    cot_agent = LLMAgentBase(["solution", "expression"], "Math Solver Agent", temperature=0.8)

    all_pairs = []  # list of tuples (solution_info, expression_info)
    for idx in range(N):
        output_infos = cot_agent([taskInfo], cot_instruction, iteration_idx=idx)
        solution_info = extract(output_infos, 'solution')
        expr_info = extract(output_infos, 'expression')
        # Guard against missing keys
        if solution_info is None or expr_info is None:
            continue
        all_pairs.append((solution_info, expr_info))

    # If no valid pairs were produced, return the first available answer
    if not all_pairs:
        return output_infos[0] if output_infos else None

    # ---------- Validate each pair ----------
    validated = []  # list of tuples (solution_info, expr_len)
    for solution_info, expr_info in all_pairs:
        sol_val = parse_num(solution_info.content)
        expr_val = eval_expr(expr_info.content)
        if sol_val is not None and expr_val is not None and abs(sol_val - expr_val) < 1e-6:
            validated.append((solution_info, len(expr_info.content)))

    # ---------- Majority vote (with tie‑break on shortest expression) ----------
    def majority_vote(pairs):
        if not pairs:
            return None
        counter = Counter([info.content for info, _ in pairs])
        best_text = counter.most_common(1)[0][0]
        candidates = [info for info, _ in pairs if info.content == best_text]
        if len(candidates) == 1:
            return candidates[0]
        expr_lengths = {info.content: l for info, l in pairs if info.content == best_text}
        best_candidate = min(expr_lengths, key=expr_lengths.get)
        return next(info for info in candidates if info.content == best_candidate)

    chosen = majority_vote(validated)
    if chosen is None:
        # Fallback to majority over all answers
        chosen = majority_vote([(info, len(e.content)) for info, e in all_pairs])

    # Final safeguard: if still None (should be impossible), return the first pair's solution
    if chosen is None and all_pairs:
        chosen = all_pairs[0][0]

    return chosen

