    import re
    import json
    from collections import Counter
    import sympy
    from math import isclose

    # ---------- Helper functions ----------
    def parse_num(s: str):
        """Return the first numeric value found in the string, or None."""
        try:
            return float(s)
        except Exception:
            m = re.search(r"[-+]?\d*\.?\d+", s)
            return float(m.group(0)) if m else None

    def eval_expr(expr_str: str):
        """Safely evaluate a mathematical expression with SymPy."""
        clean = re.sub(r"(?i)^.*?[=:]\s*", "", expr_str).replace(" ", "")
        if len(clean) > 200:
            return None
        try:
            expr = sympy.sympify(clean)
            return float(sympy.N(expr))
        except Exception:
            return None

    def extract(info_list, key):
        """Return the first Info with the given key, or None."""
        for info in info_list:
            if info.name == key:
                return info
        return None

    def validate_steps(intermediate, expression, answer):
        """Validate that the intermediate steps lead to the answer.
        intermediate: dict mapping variable → numeric value
        expression: expression string that should evaluate to answer
        answer: target numeric value
        """
        try:
            values = {k: parse_num(str(v)) for k, v in intermediate.items()}
            if any(v is None for v in values.values()):
                return False
            # Substitute variables in the expression
            substituted = expression
            for k, v in values.items():
                substituted = re.sub(rf"\b{re.escape(k)}\b", str(v), substituted)
            expr_val = eval_expr(substituted)
            if expr_val is None or not isclose(expr_val, answer, abs_tol=1e-6):
                return False
            return True
        except Exception:
            return False

    # ---------- Parameters ----------
    N = 6
    base_temp = 0.5
    temp_step = 0.05

    valid_samples = []  # list of tuples (answer_info, expression_info, step_count)
    all_answers = []    # list of tuples (answer_info, expression_info)

    for i in range(N):
        temp = min(base_temp + temp_step * i, 0.9)
        agent = LLMAgentBase(["answer", "expression", "intermediate"], f"CoT Solver {i}", temperature=temp)
        output_infos = agent(
            [taskInfo],
            "Please think step by step and then solve the task. Provide three fields: 'answer' (numeric only), 'expression' (a single mathematical expression that evaluates to the answer), and 'intermediate' (a JSON object mapping variable names to numeric values). No extra text.",
            iteration_idx=i,
        )
        answer_info = extract(output_infos, "answer")
        expression_info = extract(output_infos, "expression")
        intermediate_info = extract(output_infos, "intermediate")
        if answer_info is None or expression_info is None or intermediate_info is None:
            continue
        all_answers.append((answer_info, expression_info))
        try:
            intermediate = json.loads(intermediate_info.content)
        except Exception:
            continue
        ans_val = parse_num(answer_info.content)
        expr_val = eval_expr(expression_info.content)
        if ans_val is None or expr_val is None or not isclose(ans_val, expr_val, abs_tol=1e-6):
            continue
        if not validate_steps(intermediate, expression_info.content, ans_val):
            continue
        step_count = len(intermediate)
        valid_samples.append((answer_info, expression_info, step_count))

    # ---------- Decision ----------
    if valid_samples:
        # Choose the sample with the fewest intermediate steps
        best = min(valid_samples, key=lambda x: x[2])
        return best[0]

    # ---------- Fallback: majority vote over all answers ----------
    if not all_answers:
        # If all iterations failed, return the first available answer info
        if output_infos:
            return next((info for info in output_infos if info.name == "answer"), output_infos[0])
        return None

    counts = Counter([a.content for a, _ in all_answers])
    majority_text = counts.most_common(1)[0][0]
    majority_info = next((a for a, _ in all_answers if a.content == majority_text), all_answers[0][0])
    return majority_info

