    # Agents
    cot_agent = LLMAgentBase(["answer", "expression", "intermediate"], "CoT Solver", temperature=base_temp)
    critic_agent = LLMAgentBase(["correction"], "Critic Agent", temperature=0.7)

    for i in range(N):
        # CoT sampling
        cot_output = cot_agent([taskInfo],
