        raw_answers.append((answer_info, expr_info))

        # Parse intermediate mapping
        try:
            inter_map = json.loads(inter_info.content)
            if not isinstance(inter_map, dict):
                inter_map = None
        except Exception:
            inter_map = None

        ans_val = parse_num(answer_info.content)
        expr_val = eval_expr(expr_info.content, inter_map)

        if ans_val is None or expr_val is None or abs(ans_val - expr_val) > 1e-6:
            # Attempt correction via critic
            crit_output = critic_agent([taskInfo, answer_info, expr_info, inter_info],
                "If the intermediate steps are incorrect, produce a corrected JSON object mapping variable names to numeric values that lead to the given expression and answer. Do not add explanations.",
                iteration_idx=i)
            corr_info = extract(crit_output, 'correction')
            if corr_info:
                try:
                    corr_map = json.loads(corr_info.content)
                    if not isinstance(corr_map, dict):
                        corr_map = None
                except Exception:
                    corr_map = None
                if corr_map:
                    expr_val = eval_expr(expr_info.content, corr_map)
                    if expr_val is not None and ans_val is not None and abs(ans_val - expr_val) < 1e-6:
                        inter_map = corr_map
                        step_count = len(inter_map)
