        candidates = [(a, cnt, step) for a, cnt, step in validated if a.content == majority_text]
        if len(candidates) == 1:
            return candidates[0][0]
        # Tie: choose sample with fewest intermediate variables
        best = min(candidates, key=lambda x: x[2])
        return best[0]

    # Fallback: majority vote over all raw answers (no validation)
    if raw_answers:
