        majority_text = counts.most_common(1)[0][0]
        return next(a for a, _ in raw_answers if a.content == majority_text)

    # Last resort: return the first answer if any
    if cot_output:
        return next((info for info in cot_output if info.name == 'answer'), cot_output[0])
    return None

