        continue

    # Choose answer with highest confidence; tie‑break by fewer steps
    if validated_pairs:
        validated_pairs.sort(key=lambda x: (-x[0], len(x[2])))
        best = validated_pairs[0]
        return best[1]

    # Fallback: majority vote over all answers
    if all_answer_infos:
        counter = Counter([info.content for info in all_answer_infos])
        majority_text = counter.most_common(1)[0][0]
        majority_info = next(info for info in all_answer_infos if info.content == majority_text)
        return majority_info

    # Final fallback: first answer from the last iteration
    if last_output_infos:
        ans = next((info for info in last_output_infos if info.name == 'answer'), None)
        if ans:
            return ans

    return None

