                expr_sym = sympy.sympify(expr_str)
                equations.append(sympy.Eq(var_sym, expr_sym))
            except Exception:
                continue
        return equations

    def solve_equations(equations):
        if not equations:
            return None
        try:
            solutions = sympy.solve(equations, dict=True)
            if not solutions:
                return None
            sol = solutions[0]
        except Exception:
            return None
