    # --------- Expert Debate Agents ---------
    expert_configs = [
        {"role": "Math Professor", "temp": 0.4},
        {"role": "Grade School Teacher", "temp": 0.6},
        {"role": "Math Enthusiast", "temp": 0.8},
    ]
    experts = []
    for cfg in expert_configs:
        experts.append(
            LLMAgentBase(
                ["answer", "expression"],
                f"{cfg['role']} Agent",
                role=cfg['role'],
                temperature=cfg['temp'],
            )
        )

    max_round = 2
    # Each round will store a dict: key=agent index, value=(answer Info, expression Info)
    rounds_dicts = []

    for r in range(max_round):
        round_dict = {}
        for idx, agent in enumerate(experts):
            if r == 0:
                input_list = [taskInfo]
            else:
                prev_round = rounds_dicts[r-1]
                # build input list with task and all other agents' outputs from previous round
                input_list = [taskInfo]
                for i in range(len(experts)):
                    if i == idx:
                        continue
                    if i in prev_round:
                        input_list.append(prev_round[i][0])  # answer
                        input_list.append(prev_round[i][1])  # expression
            output_infos = agent(
                input_list,
                "Please think step by step and then solve the task. Provide two fields: 'answer' with the numeric answer only and 'expression' with a single mathematical expression that evaluates to that answer. No extra text.",
                iteration_idx=r*len(experts)+idx,
            )
            ans_info = next((info for info in output_infos if info.name == 'answer'), None)
            expr_info = next((info for info in output_infos if info.name == 'expression'), None)
            if ans_info and expr_info:
                round_dict[idx] = (ans_info, expr_info)
        rounds_dicts.append(round_dict)

