        out = solver([taskInfo._replace(content=sub_text, author="Subtask", iteration_idx=0)], instr)
        ans = next((i for i in out if i.name == "answer"), None)
        expr = next((i for i in out if i.name == "expression"), None)
        if not (ans and expr):
            return None, 0.0
        try:
            av = float(ans.content.strip())
        except Exception:
            return None, 0.0
        ev = eval_expr(expr.content)
        if ev is None or abs(ev - av) > 1e-6:
            return None, 0.0
        return ans, 1.0

    def code_solver(sub_text):
        solver = LLMAgentBase(["answer", "code"], "Code Solver", temperature=0.8)
        instr = (
            "Please think step by step and then solve the problem. Output two fields: 'answer' with the numeric answer only, and 'code' containing a short Python snippet that prints the answer. No extra text."
        )
        out = solver([taskInfo._replace(content=sub_text, author="Subtask", iteration_idx=0)], instr)
        ans = next((i for i in out if i.name == "answer"), None)
        code = next((i for i in out if i.name == "code"), None)
        if not (ans and code):
            return None, 0.0
        try:
            av = float(ans.content.strip())
        except Exception:
            return None, 0.0
        cv = safe_exec(code.content)
        if cv is None or abs(cv - av) > 1e-6:
            return None, 0.0
        return ans, 1.0

    solver_map = {
        "arithmetic": direct_solver,
        "word": expression_solver,
        "geometry": expression_solver,
        "algorithm": code_solver
    }

    # ---------- Dispatch sub‑tasks ----------
    answers = []  # list of (answer_info, confidence)
    for sub in subtasks:
        sub_text = sub.get("text") or sub.get("content")
        sub_type = sub.get("type", "arithmetic").lower()
        solver_func = solver_map.get(sub_type, direct_solver)
        ans_info, conf = solver_func(sub_text)
        if ans_info:
            answers.append((ans_info, conf))

    if not answers:
        # Fallback to direct solver on entire problem
        direct = LLMAgentBase(["answer"], "Fallback Solver", temperature=0.5)
        instr = (
            "Please think step by step and then solve the problem. Output the numeric answer in a JSON field 'answer' only. No extra text."
        )
        out = direct([taskInfo._replace(content=translated_text, author="Fallback", iteration_idx=0)], instr)
        return next((i for i in out if i.name == "answer"), None)

    # ---------- Aggregate answers ----------
    counter = Counter([a.content.strip() for a, _ in answers])
    majority_val = counter.most_common(1)[0][0]
    candidates = [(a, c) for a, c in answers if a.content.strip() == majority_val]
    best_info = max(candidates, key=lambda x: x[1])[0]
    return best_info

def forward(self, taskInfo):
    import re, math, sympy
    from collections import Counter

    # ---------- Helper: numeric extraction ----------
    def parse_num(s: str):
        try:
            return float(s.strip())
        except Exception:
            m = re.search(r"[-+]?\d*\.?\d+", s)
            return float(m.group(0)) if m else None

    # ---------- Helper: evaluate expression ----------
    def eval_expr(expr: str):
        if not expr or len(expr) > 200:
            return None
        try:
            expr_clean = re.sub(r"(?i)^.*?[=:]\s*", "", expr).replace(" ", "")
            if not expr_clean:
                return None
            expr_sym = sympy.sympify(expr_clean)
            if expr_sym.free_symbols:
                return None
            return float(expr_sym.evalf())
        except Exception:
            return None

    # ---------- Translator Agent (only if needed) ----------
    def translate(text):
        if all(ord(c) < 128 for c in text):
            return text
        translator = LLMAgentBase(["translation"], "Translator Agent", temperature=0.3)
        instr = (
            "Translate the following math problem into clear English. Output a single field 'translation' containing the translated text. No extra text."
        )
        infos = translator([taskInfo._replace(content=text, author="Original", iteration_idx=0)], instr)
        tinfo = next((i for i in infos if i.name == "translation"), None)
        return tinfo.content.strip() if tinfo else text

    translated_text = translate(taskInfo.content)

    # ---------- Debater agents ----------
    expert_configs = [
        {"role": "Math Professor", "temp": 0.4},
        {"role": "Grade School Teacher", "temp": 0.6},
        {"role": "Math Enthusiast", "temp": 0.8},
    ]
    debaters = []
    for cfg in expert_configs:
        debaters.append(
            LLMAgentBase(
                ["answer", "expression"],
                f"{cfg['role']} Agent",
                role=cfg['role'],
                temperature=cfg['temp'],
            )
        )

    debate_instruction = (
        "Please think step by step and then solve the math problem. Output two JSON fields: 'answer' with the numeric answer only (no extra text) and 'expression' with a single mathematical expression that evaluates to that answer. Do not add any explanations."
    )

    max_round = 2
    validated = []          # list of tuples (answer_info, expression_info)
    all_answer_infos = []   # list of all answer Info objects

    # Keep a single translated task object to reuse
    translated_task = taskInfo._replace(content=translated_text, author="Translated", iteration_idx=0)

    for r in range(max_round):
        for idx, agent in enumerate(debaters):
            # Update iteration index for this call
            translated_task = translated_task._replace(iteration_idx=r*len(debaters)+idx)
            output_infos = agent(
                [translated_task],
                debate_instruction,
                iteration_idx=r*len(debaters)+idx,
            )
            answer_info = next((info for info in output_infos if info.name == "answer"), None)
            expr_info   = next((info for info in output_infos if info.name == "expression"), None)
            if not (answer_info and expr_info):
                continue
            all_answer_infos.append(answer_info)

            # Validate answer and expression
            try:
                ans_val = float(answer_info.content.strip())
            except Exception:
                continue
            expr_val = eval_expr(expr_info.content)
            if expr_val is None or abs(ans_val - expr_val) > 1e-6:
                continue
            validated.append((answer_info, expr_info))

    # ---------- Decision: weighted vote over validated answers ----------
    if validated:
        # Compute weight for each answer based on expression length
        weight_map = Counter()
        for ans_info, expr_info in validated:
            weight = 1.0 / (1.0 + len(expr_info.content))
            weight_map[ans_info.content.strip()] += weight
        best_text = weight_map.most_common(1)[0][0]
        tied = [(a, e) for a, e in validated if a.content.strip() == best_text]
        if len(tied) > 1:
            best = min(tied, key=lambda x: len(x[1].content))
            return best[0]
        return next(a for a, _ in tied)

    # ---------- Fallback: majority vote over all answers ----------
    if all_answer_infos:
        counter = Counter([info.content.strip() for info in all_answer_infos])
        majority_text = counter.most_common(1)[0][0]
        best_info = next((info for info in all_answer_infos if info.content.strip() == majority_text), all_answer_infos[0])
        return best_info

    # ---------- Final fallback: single-pass CoT solver ----------
    simple_agent = LLMAgentBase(["answer"], "Simple CoT Agent", temperature=0.5)
    simple_instruction = (
        "Please think step by step and then solve the problem. Output the numeric answer in a JSON field 'answer' only. No extra text."
    )
    simple_output = simple_agent([taskInfo], simple_instruction)
    return next((info for info in simple_output if info.name == "answer"), None)
